import { pcm16 } from './audio';

export const encodeMp3 = async (audio: AudioBuffer): Promise<Blob> => {
  // Load the encoder only when an MP3 is requested.
  const { Mp3Encoder } = await import('@breezystack/lamejs');
  const encoder = new Mp3Encoder(2, audio.sampleRate, 192);
  const left = audio.getChannelData(0);
  const right = audio.getChannelData(Math.min(1, audio.numberOfChannels - 1));
  const parts: Uint8Array[] = [];
  const blockSize = 1152;
  for (let offset = 0; offset < audio.length; offset += blockSize) {
    const length = Math.min(blockSize, audio.length - offset);
    const l = new Int16Array(length);
    const r = new Int16Array(length);
    for (let i = 0; i < length; i++) {
      l[i] = pcm16(left[offset + i]);
      r[i] = pcm16(right[offset + i]);
    }
    const encoded = encoder.encodeBuffer(l, r);
    if (encoded.length) parts.push(new Uint8Array(encoded));
    if (offset % (blockSize * 32) === 0) {
      await new Promise(resolve => setTimeout(resolve, 0));
    }
  }
  parts.push(new Uint8Array(encoder.flush()));
  return new Blob(parts, { type: 'audio/mpeg' });
};
